namespace UnityEngine {
 public class Object {public static T Instantiate<T>(T prefab,Transform parent,bool world) where T:Object{return (T)(Object)new GameObject("row",typeof(KeyValueField));}}
 public class Component:Object {public GameObject gameObject;public Transform transform{get{return gameObject.transform;}}public T GetComponent<T>() where T:class{return gameObject.GetComponent<T>();}public T[] GetComponentsInChildren<T>(bool a){return new T[0];}}
 public class MonoBehaviour:Component{}public class Transform:Component {public string name;public Transform parent;public Transform Find(string n){return null;}public void SetParent(Transform p,bool b){parent=p;}public void SetAsFirstSibling(){}public void SetAsLastSibling(){}}
 public class RectTransform:Transform{public Vector2 sizeDelta,anchorMin,anchorMax,offsetMin,offsetMax;public Rect rect=new Rect{width=210};}public class GameObject:Object {Dictionary<Type,object> components=new Dictionary<Type,object>();public string name;public bool activeSelf,activeInHierarchy=true;public Transform transform;public GameObject(string n,params Type[] types){name=n;transform=new RectTransform{gameObject=this};foreach(var t in types)if(t!=typeof(RectTransform))AddComponent(t);}object AddComponent(Type t){if(typeof(UnityEngine.UI.Selectable).IsAssignableFrom(t)){foreach(var old in components.Values)if(old is UnityEngine.UI.Selectable)throw new InvalidOperationException("Selectable already exists on this native prefab object");}var v=Activator.CreateInstance(t);if(v is Component)((Component)v).gameObject=this;components[t]=v;return v;}public T AddComponent<T>() where T:new(){return (T)AddComponent(typeof(T));}public T GetComponent<T>() where T:class{object v;return components.TryGetValue(typeof(T),out v)?v as T:null;}public void SetActive(bool b){activeSelf=b;activeInHierarchy=b;}}
 public static class Resources{public static T Load<T>(string p) where T:class{return new GameObject("prefab") as T;}}public static class Debug{public static void LogWarning(object e){}}public static class Time{public static float unscaledTime;}public enum HorizontalWrapMode{Wrap,Overflow}public enum TextAnchor{MiddleRight}public struct Vector2{public float x,y;public Vector2(float a,float b){x=a;y=b;}public static Vector2 zero;}public struct Rect{public float width;}public struct Color{public Color(float r,float g,float b,float a){}}public enum VerticalWrapMode{Truncate}
